<?php
declare(strict_types=1);
require_once __DIR__.'/date-time.php';
require_once __DIR__.'/localization.php';
require_once __DIR__.'/legal.php';
function nodenoPaymentDocumentAddress(array $address):string {return implode("\n",array_filter(array_map(static fn($key)=>(string)($address[$key]??''),['name','line1','line2','district','city','postalCode','country'])));}
function nodenoPaymentDocumentOptions(array $line,string $locale):string {
 $variant=$line['variant']??'';if(is_array($variant))$variant=nodenoLocaleLocal($variant,$locale);$parts=array_filter([(string)$variant]);$options=$line['options']??[];
 if(isset($options['widthMm'],$options['heightMm']))$parts[]=$options['widthMm'].' × '.$options['heightMm'].' mm';
 if(isset($options['leafWidthMm'],$options['heightMm']))$parts[]=$options['leafWidthMm'].' × '.$options['heightMm'].' mm';
 if(isset($options['frameWidthMm']))$parts[]=$options['frameWidthMm'].' mm';
 if(!isset($options['heightMm'])&&isset($options['height']))$parts[]=$options['height'].' cm';if(!isset($options['frameWidthMm'])&&isset($options['frameDepth']))$parts[]=$options['frameDepth'].' cm';if(!empty($options['openingWidthMm']))$parts[]=$options['openingWidthMm'].' mm';
 $words=nodenoLocaleCopy(['tr'=>['left'=>'Sol','right'=>'Sağ','unspecified'=>'Açılış yönü belirlenmedi','glazed'=>'Camlı','hardware'=>'Kilit, menteşe ve fitil','architrave18'=>'18 mm pervaz','handle'=>'Kapı kolu talebi','solid'=>'Düz kapak','drawer'=>'Çekmece klapası','long'=>'Boy kapak'], 'en'=>['left'=>'Left','right'=>'Right','unspecified'=>'Handing undecided','glazed'=>'Glazed','hardware'=>'Lock, hinges and seal','architrave18'=>'18 mm architrave','handle'=>'Handle requested','solid'=>'Solid front','drawer'=>'Drawer front','long'=>'Full-height front'], 'ru'=>['left'=>'Левое','right'=>'Правое','unspecified'=>'Направление не выбрано','glazed'=>'Остекление','hardware'=>'Замок, петли и уплотнитель','architrave18'=>'Наличник 18 мм','handle'=>'Запрос ручки','solid'=>'Глухой фасад','drawer'=>'Фасад ящика','long'=>'Высокий фасад'], 'ar'=>['left'=>'يسار','right'=>'يمين','unspecified'=>'اتجاه الفتح غير محدد','glazed'=>'زجاج','hardware'=>'قفل ومفصلات وشريط إحكام','architrave18'=>'إطار تغطية 18 مم','handle'=>'طلب مقبض','solid'=>'واجهة مصمتة','drawer'=>'واجهة درج','long'=>'واجهة كاملة الارتفاع']],$locale)??[];
 foreach(['handing','application']as $key)if(isset($options[$key]))$parts[]=$words[$options[$key]]??$options[$key];foreach(['glazed','hardware','architrave18','handle']as $key)if(!empty($options[$key]))$parts[]=$words[$key]??$key;
 foreach(['glassModelId','surface']as $key)if(isset($options[$key])&&is_scalar($options[$key]))$parts[]=(string)$options[$key];
 return implode(' · ',$parts);
}

function nodenoPaymentEnsureDocuments(PDO $db,string $root,array $order):void {
 $db->exec('CREATE TABLE IF NOT EXISTS payment_documents(order_id TEXT PRIMARY KEY REFERENCES payment_orders(id),html_envelope TEXT NOT NULL,sha256 TEXT NOT NULL,created_at INTEGER NOT NULL,served_at INTEGER)');
 nodenoControlTransaction($db,static function()use($db,$root,$order):void{
  $s=$db->prepare('SELECT order_id FROM payment_documents WHERE order_id=?');$s->execute([$order['id']]);if($s->fetchColumn())return;
  $locale=$order['locale'];$labels=nodenoLegalLabels($locale);$e='nodenoLegalEscape';$quote=json_decode($order['snapshot_json'],true,64,JSON_THROW_ON_ERROR);$seller=json_decode($order['seller_json'],true,64,JSON_THROW_ON_ERROR);$contact=nodenoPaymentPrivate($root,$order)['contact'];
  $money=static fn($n)=>number_format((int)$n/100,2,'.','').' '.$quote['currency'];
  $html='<!doctype html><html lang="'.$e($locale).'" dir="'.(nodenoLocaleRtl($locale)?'rtl':'ltr').'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NODENO '.$e($order['id']).'</title><style>body{font:16px/1.7 Arial,sans-serif;color:#172d38;max-width:850px;margin:40px auto;padding:24px}h1{font-size:28px}h2{font-size:21px}p{white-space:pre-line;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%}th,td{border-bottom:1px solid #daddd6;padding:12px;text-align:start}small{color:#536770}@media print{body{margin:0;padding:12px}}</style></head><body><h1>NODENO — '.$e($labels['sales']).'</h1><p>'.$e($labels['copy']).'</p><p>'.$e($order['id']).' · '.$e(nodenoHumanDateTime((int)$order['created_at'],(string)($quote['country']??$contact['delivery']['country']??'TR'))).'</p><p>'.$e($labels['version']).': '.$e($seller['termsVersion']??'').'</p><h2>'.$e($labels['seller']).'</h2><p>'.$e(implode("\n",[$seller['name']??'',$seller['address']??'',$seller['email']??''])).'</p><h2>'.$e($labels['buyer']).'</h2><p>'.$e(implode("\n",array_filter([$contact['name']??'',$contact['email']??'',$contact['phone']??'',nodenoPaymentDocumentAddress($contact['delivery']??[]),isset($contact['billing'])?nodenoPaymentDocumentAddress($contact['billing']):'']))).'</p><h2>'.$e($labels['order']).'</h2><table><thead><tr><th>'.$e($labels['order']).'</th><th>'.$e($labels['quantity']).'</th><th>'.$e($labels['total']).'</th></tr></thead><tbody>';
  foreach($quote['lines']as $line){$name=$line['name']??$line['id'];if(is_array($name))$name=nodenoLocaleLocal($name,$locale);$html.='<tr><td>'.$e($name).'<p>'.$e(nodenoPaymentDocumentOptions($line,$locale)).'</p></td><td>'.$e($line['quantity']??'').'</td><td>'.$e($money($line['totalMinor']??0)).'</td></tr>';}
  $html.='</tbody></table><p>'.$e($labels['net']).': '.$e($money($quote['netMinor']))."\n".$e($labels['vat']).': '.$e($money($quote['vatMinor']))."\n".$e($labels['total']).': <strong>'.$e($money($quote['totalMinor'])).'</strong></p><p>'.$e(($quote['freight']['kind']??'')==='included'?nodenoLocaleCopy(['tr'=>'Türkiye içi kargo fiyatlara dahildir.','en'=>'Shipping within Türkiye is included.','ru'=>'Доставка по Турции включена.','ar'=>'الشحن داخل تركيا مشمول.'],$locale):$labels['freight']).'</p><h2>'.$e($labels['pre-information']).' / '.$e($labels['sales']).'</h2><p>'.$e(nodenoLocaleDocument($seller['terms']??[],$locale)).'</p><h2>'.$e($labels['returns']).'</h2><p>'.$e(nodenoLocaleDocument($seller['returns']??[],$locale)).'</p></body></html>';
  $hash=hash('sha256',$html);$envelope=nodenoControlEncrypt($root,$html,'payment-documents:'.$order['id']);$db->prepare('INSERT INTO payment_documents(order_id,html_envelope,sha256,created_at) VALUES(?,?,?,?)')->execute([$order['id'],$envelope,$hash,time()]);
 });
}
function nodenoPaymentDocument(PDO $db,string $root,array $order,?string $userId,string $actor):array {
 $actorHash=hash_hmac('sha256',$actor,nodenoControlKey($root));if(!(is_string($order['user_id']??null)&&$userId!==null&&hash_equals($order['user_id'],$userId))&&!hash_equals($order['actor_hash'],$actorHash))throw new NodenoControlHttpError(403,'payment_document_access_denied');
 $s=$db->prepare('SELECT * FROM payment_documents WHERE order_id=?');$s->execute([$order['id']]);$row=$s->fetch();if(!$row)throw new NodenoControlHttpError(404,'payment_document_unavailable');
 $html=nodenoControlDecrypt($root,$row['html_envelope'],'payment-documents:'.$order['id']);if(!hash_equals($row['sha256'],hash('sha256',$html)))throw new RuntimeException('payment_document_integrity');return ['html'=>$html,'sha256'=>$row['sha256']];
}
